INSERT INTO `book` VALUES (1,'books/main/2025/10/nha-gia-kim-1.jpg','Nhà Giả Kim','“Nhà giả kim” là tiểu thuyết nổi tiếng của Paulo Coelho, kể về hành trình theo đuổi ước mơ của chàng chăn cừu Santiago trên con đường tìm kiếm kho báu - một ẩn dụ về hành trình tìm ra ý nghĩa của cuộc sống','nha-gia-kim','Paulo Coelho','NXB Văn Học','1988-04-15','Tiếng Việt',89000.00,120,'2025-10-12 05:53:13.558831','2025-10-20 09:25:25.052379',0,5),(2,'books/main/2025/10/dac-nhan-tam-1.jpg','Đắc Nhân Tâm','“Đắc Nhân Tâm” (How to Win Friends and Influence People) là cuốn sách kinh điển của Dale Carnegie, hướng dẫn nghệ thuật ứng xử, giao tiếp và thuyết phục người khác. Tác phẩm giúp người đọc hiểu sâu hơn về tâm lý con người, từ đó xây dựng các mối quan hệ tốt đẹp trong công việc và cuộc sống.','dac-nhan-tam','Dale Carnegie','NXB Tổng hợp TP.HCM','2018-05-01','Tiếng Việt',79000.00,60,'2025-10-13 01:39:39.709567','2025-10-13 01:40:04.987583',0,5),(3,'books/main/2025/10/day-con-lam-giau-tap-2.jpg','Dạy Con Làm Giàu','Dạy Con Làm Giàu – Tập 1: Cha Giàu, Cha Nghèo” là cuốn sách kinh điển giúp thay đổi tư duy về tiền bạc, đầu tư và tự do tài chính. Robert Kiyosaki kể lại câu chuyện về hai người cha – “cha nghèo” (cha ruột) và “cha giàu” (cha của người bạn thân) – để minh họa hai cách nghĩ hoàn toàn khác nhau về tiền bạc và con đường đi đến giàu có','day-con-lam-giau','Robert T. Kiyosaki','NXB Trẻ','2019-10-15','Tiếng Việt',129000.00,120,'2025-10-13 01:44:28.556852','2025-10-13 01:44:52.432856',0,4),(4,'books/main/2025/10/gioi-thieu-7-thoi-quen-hieu-qua.jpg','7 Thói Quen Hiệu Quả','Stephen R. Covey giới thiệu 7 thói quen nền tảng giúp con người phát triển bản thân, nâng cao hiệu quả làm việc và xây dựng mối quan hệ bền vững. Cuốn sách được xem là kim chỉ nam cho những ai muốn thay đổi tích cực cuộc sống.','7-thoi-quen-hieu-qua','Stephen R. Covey','NXB Trẻ','2017-08-15','Tiếng Việt',159000.00,60,'2025-10-13 01:48:28.139145','2025-10-13 02:12:17.686795',0,5),(5,'books/main/2025/10/tuoi-tre-dang-gia-bao-nhieu-1.jpg','Tuổi Trẻ Đáng Giá Bao Nhiêu','Cuốn sách của Rosie Nguyễn dành cho người trẻ, khơi gợi cảm hứng sống có mục tiêu, biết tự học, khám phá và phát triển bản thân trong những năm tháng thanh xuân. Một lời nhắn nhủ chân thành: hãy sống trọn vẹn với tuổi trẻ.','tuoi-tre-dang-gia-bao-nhieu','Rosie Nguyễn','NXB Hội Nhà Văn','2016-10-20','Tiếng Việt',89000.00,70,'2025-10-13 01:48:28.242668','2025-10-13 02:12:33.844290',0,8),(6,'books/main/2025/10/16123315.jpg','Không Gia Đình','Tác phẩm nổi tiếng của Hector Malot kể về cuộc đời phiêu lưu của cậu bé mồ côi Rémi, tràn đầy lòng nhân hậu và nghị lực sống mạnh mẽ. Một câu chuyện xúc động về tình người và lòng dũng cảm.','khong-gia-dinh','Hector Malot','NXB Kim Đồng','2015-02-05','Tiếng Việt',105000.00,50,'2025-10-13 01:48:28.247670','2025-10-13 02:12:44.524397',0,2),(7,'books/main/2025/10/z5382052575312_b21c976817e14ec93c131e87dddc3dd7_20240523191338_20240524160319.jpg','Totto-chan: Cô Bé Bên Cửa Sổ','Cuốn hồi ký cảm động của Tetsuko Kuroyanagi kể về tuổi thơ của cô tại ngôi trường đặc biệt Tomoe. Sách tôn vinh giáo dục nhân văn, tự do và sáng tạo trong trẻ nhỏ.','totto-chan-co-be-ben-cua-so','Tetsuko Kuroyanagi','NXB Kim Đồng','2014-09-09','Tiếng Việt',99000.00,65,'2025-10-13 01:48:28.252922','2025-10-13 02:12:58.935894',0,9),(8,'books/main/2025/10/2021_07_01_10_05_44_1-390x510.jpg','Bí Mật Của Phan Thiên Ân','Tác phẩm truyền cảm hứng về niềm tin, nghị lực và sự thay đổi bản thân để đạt thành công.','bi-mat-cua-phan-thien-an','Og Mandino','NXB Lao Động','2015-09-09','Tiếng Việt',99000.00,75,'2025-10-13 01:50:21.807812','2025-10-13 02:13:23.231532',0,1),(9,'books/main/2025/10/sds-kd-trv-234.jpg','Người Giàu Có Nhất Thành Babylon','Tập hợp những bài học kinh điển về quản lý tài chính và đầu tư thông minh qua các câu chuyện ngụ ngôn.','nguoi-giau-co-nhat-thanh-babylon','George S. Clason','NXB Lao Động Xã Hội','2018-11-01','Tiếng Việt',99000.00,110,'2025-10-13 01:50:21.812629','2025-10-13 02:13:32.873664',0,4),(10,'books/main/2025/10/dung_lua_chon_an_nhan_khi_con_tre_tai_ban_.jpg','Đừng Lựa Chọn An Nhàn Khi Còn Trẻ','Cuốn sách giúp người trẻ nhận ra giá trị của nỗ lực và hành trình vượt qua giới hạn bản thân.','dung-lua-chon-an-nhan-khi-con-tre','Cảnh Thiên','NXB Lao Động','2021-04-22','Tiếng Việt',79000.00,150,'2025-10-13 01:50:21.815854','2025-10-13 02:13:49.096872',0,8),(11,'books/main/2025/10/2025_01_06_14_31_09_1-390x510.jpg','Kẻ Trộm Sách','Tiểu thuyết lấy bối cảnh Đức quốc xã, kể về cô bé Liesel và sức mạnh của ngôn từ giữa chiến tranh.','ke-trom-sach','Markus Zusak','NXB Văn Học','2019-02-01','Tiếng Việt',145000.00,55,'2025-10-13 01:50:21.818230','2025-10-13 02:18:12.019867',0,10),(12,'books/main/2025/10/8935270703554.jpg','Sapiens: Lược Sử Loài Người','Yuval Noah Harari kể lại hành trình phát triển của nhân loại từ thời tiền sử đến kỷ nguyên công nghệ.','sapiens-luoc-su-loai-nguoi','Yuval Noah Harari','NXB Thế Giới','2020-10-10','Tiếng Việt',269000.00,40,'2025-10-13 01:50:21.820471','2025-10-13 02:19:46.514802',0,7),(13,'books/main/2025/10/nxbtre_full_12282017_032853.jpg','Trên Đường Băng','Tony Buổi Sáng tổng hợp các bài viết về tư duy làm việc, học tập và khởi nghiệp cho người trẻ.','tren-duong-bang','Tony Buổi Sáng','NXB Trẻ','2017-01-01','Tiếng Việt',95000.00,80,'2025-10-13 01:50:21.822464','2025-10-13 02:20:48.139350',0,2),(14,'books/main/2025/10/nxbtre_full_19482018_034833.jpg','Đời Ngắn Đừng Ngủ Dài','Robin Sharma chia sẻ bí quyết sống trọn vẹn, hiệu quả và có ý nghĩa mỗi ngày.','doi-ngan-dung-ngu-dai','Robin Sharma','NXB Trẻ','2018-12-01','Tiếng Việt',99000.00,100,'2025-10-13 01:50:21.824391','2025-10-13 02:22:07.173901',0,10),(15,'books/main/2025/10/20240507_dySgtJu4wW.jpg','Thiên Tài Bên Trái Kẻ Điên Bên Phải','Khám phá ranh giới giữa thiên tài và điên loạn qua các câu chuyện tâm lý học có thật !','thien-tai-ben-trai-ke-dien-ben-phai','Cao Minh','NXB Lao Động','2021-03-01','Tiếng Việt',139000.00,65,'2025-10-13 01:50:21.826302','2025-10-16 16:09:13.590772',0,5),(16,'books/main/2025/10/unnamed_1.jpg','Tôi Tài Giỏi, Bạn Cũng Thế!','Adam Khoo chia sẻ bí quyết học tập hiệu quả và phát triển bản thân dành cho giới trẻ.','toi-tai-gioi-ban-cung-the','Adam Khoo','NXB Trẻ','2016-05-10','Tiếng Việt',95000.00,130,'2025-10-13 01:50:21.828491','2025-10-13 02:25:30.456525',0,5),(17,'books/main/2025/10/Hành_trình_về_phương_Đông_-_Ảnh_bìa.jpg','Hành Trình Về Phương Đông','Tác phẩm kinh điển về hành trình tâm linh, triết lý sống và tinh thần giác ngộ phương Đông.','hanh-trinh-ve-phuong-dong','Baird T. Spalding','NXB Văn Hóa – Thông Tin','2015-03-01','Tiếng Việt',88000.00,75,'2025-10-13 01:50:21.831280','2025-10-13 02:28:00.669810',0,2),(18,'books/main/2025/10/chienbinhcauvong.jpg','Chiến Binh Cầu Vồng','Câu chuyện cảm động về hành trình vượt khó của thầy trò trường làng ở Indonesia.','chien-binh-cau-vong','Andrea Hirata','NXB Trẻ','2018-04-01','Tiếng Việt',115000.00,85,'2025-10-13 01:50:21.834114','2025-10-13 02:29:41.707509',0,9),(19,'books/main/2025/10/nguoibanhangvidainhatthegioi.png','Người Bán Hàng Vĩ Đại Nhất Thế Giới','Og Mandino truyền tải thông điệp về nghị lực, niềm tin và bí quyết để thành công trong kinh doanh.','nguoi-ban-hang-vi-dai-nhat-the-gioi','Og Mandino','NXB Lao Động','2016-08-05','Tiếng Việt',79000.00,90,'2025-10-13 01:50:21.836774','2025-10-13 02:32:28.058656',0,4),(20,'books/main/2025/10/23276781.jpg','Cà Phê Cùng Tony','Những mẩu chuyện hài hước, sâu sắc về lối sống, tư duy làm việc và cách phát triển bản thân của người trẻ.','ca-phe-cung-tony','Tony Buổi Sáng','NXB Trẻ','2015-09-09','Tiếng Việt',85000.00,75,'2025-10-13 01:50:21.839186','2025-10-13 02:34:14.006500',0,8),(21,'books/main/2025/10/16.-Di-tim-le-song-Viktor-Emil-Frankl.jpg','Đi Tìm Lẽ Sống','Viktor E. Frankl chia sẻ trải nghiệm trong trại tập trung và hành trình tìm ý nghĩa cuộc sống.','di-tim-le-song','Viktor E. Frankl','NXB Tổng Hợp TP.HCM','2020-05-05','Tiếng Việt',129000.00,60,'2025-10-13 01:50:21.841871','2025-10-13 02:43:33.923353',0,2),(22,'books/main/2025/10/z4105964911654-5e5a35259898ca70607286170319aa65.jpg','Sức Mạnh Của Thói Quen','Charles Duhigg lý giải cách hình thành thói quen và cách biến nó thành công cụ thay đổi cuộc đời.','suc-manh-cua-thoi-quen','Charles Duhigg','NXB Trẻ','2018-06-12','Tiếng Việt',159000.00,90,'2025-10-13 01:50:21.844632','2025-10-13 02:46:22.955813',0,5),(23,'books/main/2025/10/buocchamlaigiuathegianvoiva01-4e74490c-3e27-444a-8edc-eb3d5278892e.jpg','Bước Chậm Lại Giữa Thế Gian Vội Vã','Hae Min chia sẻ những chiêm nghiệm sâu sắc về cuộc sống, tình yêu và sự bình an nội tâm.','buoc-cham-lai-giua-the-gian-voi-va','Hae Min','NXB Văn Học','2019-09-09','Tiếng Việt',99000.00,85,'2025-10-13 01:50:21.847412','2025-10-13 02:47:42.250779',0,5),(24,'books/main/2025/10/5931ef78-106f-489c-a3e6-11f9f665489d-174049073144472477311.jpg','Trên Đường Đời Gặp Gỡ Chính Mình','Rando Kim viết về sự trưởng thành, tình yêu và hạnh phúc qua những góc nhìn nhân văn.','tren-duong-doi-gap-go-chinh-minh','Rando Kim','NXB Trẻ','2017-07-07','Tiếng Việt',89000.00,100,'2025-10-13 01:50:21.850170','2025-10-13 02:49:52.956153',0,1),(25,'books/main/2025/10/1_14b86c8e1fb24290b2ca9d80d3c3e4ac_master.jpg','Tâm Lý Học Tội Phạm','Khám phá tâm lý tội phạm và quá trình điều tra qua góc nhìn của chuyên gia tâm lý hình sự.','tam-ly-hoc-toi-pham','Stanton E. Samenow','NXB Lao Động','2022-02-22','Tiếng Việt',165000.00,45,'2025-10-13 01:50:21.852597','2025-10-13 02:51:28.219318',0,5),(26,'books/main/2025/10/nha_tho_duc_ba_paris__1_2018_07_20_17_00_29.jpg','Nhà Thờ Đức Bà Paris','Kiệt tác của Victor Hugo kể về bi kịch tình yêu và số phận con người dưới mái vòm Paris.','nha-tho-duc-ba-paris','Victor Hugo','NXB Văn Học','2014-04-04','Tiếng Việt',145000.00,50,'2025-10-13 01:50:21.855308','2025-10-13 02:55:08.311222',0,7),(27,'books/main/2025/10/2022_12_23_11_18_14_1-390x510.jpg','Marie Curie - Nhà Nữ Khoa Học Kiệt Xuất','Cuốn sách gồm những câu chuyện viết về cuộc đời của nhà nữ khoa học kiệt xuất: Marie Curie. Ngay từ nhỏ, bà đã bộc lộ tư chất thông minh hơn người và lòng say mê khoa học. Năm 24 tuổi, Marie học tại trường Đại học Sorbone danh tiếng ở Paris và là một trong những sinh viên xuất sắc nhất của trường. Cũng tại Pháp, Marie Curie đã gặp và kết hôn với nhà vật lý danh tiếng người Pháp - Pierre Curie. Có chung niềm đam mê khoa học, hai vợ chồng làm việc gần như làm việc không ngừng nghỉ. Sau một loạt các nghiên cứu, thí nghiệm, cuối cùng họ đã phát hiện ra hai nguyên tố hóa học mới: polonium và radium. Với những đóng góp to lớn của mình, bà đã được trao giải Nobel Vật lý cùng chồng và Henri Becquerel năm 1903 và giải Nobel Hóa học năm 1911.\r\nNgày 20 tháng 4 năm 1995, trong một nghi lễ long trọng, thi hài của hai vợ chồng bà được chuyển tới Điện Panthéon – nơi chôn cất những danh nhân của nước Pháp. Không những thế, các nhà khoa học còn đặt tên Curium cho nguyên tố hóa học số 96 trong bảng tuần hoàn để vinh danh hai người. Năm 2011, nhà nữ khoa học đứng đầu trong danh sách 100 phụ nữ thay đổi thế giới do độc giả của BBC History bình chọn. \r\nMarie Curie sinh ngày 7 tháng 11 năm 1867 tại Ba Lan, mất ngày 4 tháng 7 năm 1934 tại Pháp. Bà là nhà nữ khoa học đầu tiên trên thế giới giành giải Nobel, là người phụ nữ duy nhất nhận hai giải Nobel trong hai lĩnh vực khác nhau: vật lý và hóa học. Cuộc đời của bà gắn liền với các nghiên cứu về phóng xạ, chính bà còn đưa ra thuật ngữ phóng xạ. Bà không chỉ là một nhà khoa học lỗi lạc, mà còn là một người có lòng yêu nước nồng nàn và lòng nhân ái cao cả.','marie-curie-nha-nu-khoa-hoc-kiet-xuat','Rasmus Hoài Nam','NXB Thanh Niên','2021-10-17','Tiếng Anh',60000.00,40,'2025-10-17 10:14:21.547326','2025-10-17 10:14:21.839305',0,8),(28,'books/main/2025/10/2021_06_08_16_14_00_1-390x510.jpg','Rừng Khộp Mùa Thay Lá','Với giọng văn bình dị, mộc mạc, như lời kể thủ thỉ của một đồng đội lúc đêm khuya, Nguyễn Vũ Điền gợi những cảm xúc tràn đầy, sâu đậm. Hình ảnh những người lính hiện lên trong từng trang viết chân thật, đầy chất lính và chất con người.\r\nNgười lính, qua ngòi bút của tác giả Nguyễn Vũ Điền, là những thanh niên trong sáng, có đôi phần ngây thơ khi mới chập chững bước vào quân ngũ. Nhưng qua những trận đánh, những mất mát, vốn quá nhiều trong đời người lính chiến, tác giả và các đồng đội đã trở thành những chiến binh thực thụ; đã nếm trải những vui buồn, mất mát, bao lần nhìn đồng đội ra đi mãi mãi trong lứa tuổi thanh xuân, đã nếm trải tình cảm thân thương với những người mẹ, người em gái Khmer hiền lành chất phác.','rung-khop-mua-thay-la','Nguyễn Vũ Điền','NXB Trẻ','2019-10-21','Tiếng Việt',89000.00,20,'2025-10-21 13:38:01.472653','2025-10-21 13:38:01.743001',0,1),(29,'books/main/2025/10/2021_06_21_14_56_13_1-390x510.jpg','Màu Rừng Ruộng','Câu chuyện đan xen giữa hồi ức, hiện tại và giấc mơ tương lai của Vinh, một người lính - cuộc đi tìm hài cốt đồng đội và cái chết bi tráng của anh. Bối cảnh chính là làng Bùi nhỏ bé thuộc Bắc bộ và những khu rừng đại ngàn ở làng Sập của Tây Nguyên. Tiểu thuyết có nhiều tình tiết khá hấp dẫn, hiện thực ngồn ngộn và dữ dội.','mau-rung-ruong','Đỗ Tiến Thụy','NXB Trẻ','2018-10-21','Tiếng Việt',76500.00,20,'2025-10-21 13:41:04.873023','2025-10-21 13:41:04.888028',0,1),(30,'books/main/2025/10/2020_06_11_14_53_14_1-390x510.jpg','Mùa Xa Nhà (Tái Bản 2019)','Mùa xa nhà là cuốn tiểu thuyết kể lại giai đoạn làm lính tình nguyện của Huy, chàng trai thành phố đi nghĩa vụ quân sự, có mặt và sống chiến đấu ở một đơn vị hỏa lực bộ binh trong những năm giữa thập niên 80 thế kỷ 20 ở vùng rừng phía Tây Bắc Campuchia xa xôi.\r\nTừ một chàng trai thư sinh, Huy đã dần quen với cuộc sống. Ở đó Huy không chỉ làm quen với nhiều chàng trai thành phố khác nhập ngũ trước mình, mà còn bè bạn và chịu sự chỉ huy của những chàng trai từ khắp miền Tổ quốc làm nhiệm vụ lính tình nguyện ở Campuchia.\r\nNhững vui buồn, hờn giận, những mất mát đau thương, cả những trận chiến đấu nẩy lửa… cứ từng bước tôi cho chàng lính trẻ lần đầu tiên xa nhà trải qua 3 năm chiến trận trở thành một cán bộ trung đội rắn rõi và đầy bản lĩnh. Anh yên lành trở về thành phố, kết thúc mùa xa nhà của đời lính trong sự thay đổi đến ngỡ ngàng.','mua-xa-nha','Nguyễn Thành Nhân','NXB Trẻ','2017-10-21','Tiếng Việt',120000.00,20,'2025-10-21 13:43:57.700594','2025-10-21 13:43:57.772627',0,1);
